 * @param {React.ReactNode} props.children - Content to render inside the layout.
 * @param {string} props.className - Additional classes for custom styling.
 */
const Layout = ({ centered, children, className = '' }) => {
  // Calculate the container classes based on the variant
  const containerClasses = centered 
    ? 'mx-auto max-w-4xl px-4' // Centered variant: Horizontal padding + Centered alignment
    : 'w-full px-4';           // Full-width variant: Horizontal padding only

  // Merge the variant classes with any user-provided extra classes
  const combinedClasses = `layout-wrapper ${containerClasses} ${className}`;

  return (
    <div className={combinedClasses}>
      {children}
    </div>
  );
};

export default Layout;
